settings.custom_liquid:
{%- liquid
  assign nm_upsell = 'loupe-de-date-saphir,bracelet-fkm-tropical,rouleau-de-voyage-cuir,remontoir-solo' | split: ','
  assign nm_count = 0
-%}
{%- capture nm_upsell_items -%}
  {%- for h in nm_upsell -%}
    {%- if nm_count >= 2 -%}{%- break -%}{%- endif -%}
    {%- assign p = all_products[h] -%}
    {%- if p != empty and p.available -%}
      {%- assign in_cart = false -%}
      {%- for item in cart.items -%}
        {%- if item.product.handle == h -%}{%- assign in_cart = true -%}{%- endif -%}
      {%- endfor -%}
      {%- unless in_cart -%}
        {%- assign v = p.selected_or_first_available_variant -%}
        <div class="nm-cart-upsell__item">
          <a href="{{ p.url }}" class="nm-cart-upsell__media"><img src="{{ p.featured_image | image_url: width: 160 }}" alt="{{ p.title | escape }}" width="56" height="56" loading="lazy"></a>
          <div class="nm-cart-upsell__info">
            <a href="{{ p.url }}" class="nm-cart-upsell__name">{{ p.title }}</a>
            <div class="nm-cart-upsell__row">
              <span class="nm-cart-upsell__price">{{ v.price | money }}</span>
              <form method="post" action="{{ routes.cart_add_url }}" class="nm-upsell-form" data-nm-upsell>
                <input type="hidden" name="id" value="{{ v.id }}">
                <input type="hidden" name="quantity" value="1">
                <button type="submit" class="nm-upsell-add">Ajouter</button>
              </form>
            </div>
          </div>
        </div>
        {%- assign nm_count = nm_count | plus: 1 -%}
      {%- endunless -%}
    {%- endif -%}
  {%- endfor -%}
{%- endcapture -%}
{%- assign nm_trim = nm_upsell_items | strip -%}
{%- if nm_trim != '' -%}
<div class="nm-cart-upsell">
  <p class="nm-cart-upsell__title">Complétez votre collection</p>
  <div class="nm-cart-upsell__list">{{ nm_upsell_items }}</div>
</div>
{%- endif -%}
<style>
  .nm-cart-upsell{padding-block:var(--gap-md,.75rem);border-top:1px solid rgb(11 11 12 / .08);margin-block-start:var(--gap-sm,.5rem)}
  .nm-cart-upsell__title{font-family:var(--font-heading--family,inherit);color:#0B0B0C;font-size:1.02rem;margin:0 0 .8rem}
  .nm-cart-upsell__list{display:flex;flex-direction:column;gap:.9rem}
  .nm-cart-upsell__item{display:grid;grid-template-columns:56px 1fr;align-items:center;gap:.75rem}
  .nm-cart-upsell__media{display:block}
  .nm-cart-upsell__item img{width:56px;height:56px;object-fit:cover;border-radius:10px;background:#E7E4DE;display:block}
  .nm-cart-upsell__info{display:flex;flex-direction:column;gap:.35rem;min-width:0}
  .nm-cart-upsell__name{font-size:.85rem;line-height:1.25;color:#0B0B0C;text-decoration:none}
  .nm-cart-upsell__name:hover{text-decoration:underline}
  .nm-cart-upsell__row{display:flex;align-items:center;justify-content:space-between;gap:.5rem}
  .nm-cart-upsell__price{font-size:.9rem;font-weight:600;color:#0B0B0C;white-space:nowrap}
  .nm-upsell-form{margin:0}
  .nm-upsell-add{border:0;cursor:pointer;background:#0B0B0C;color:#FAFAF7;font-size:.78rem;font-weight:600;padding:.4rem .85rem;border-radius:999px;white-space:nowrap;transition:background .15s ease}
  .nm-upsell-add:hover{opacity:.88}
</style>
<script>
  (function () {
    if (window.__nmUpsellBound) return;
    window.__nmUpsellBound = true;
    document.addEventListener('submit', function (e) {
      var f = e.target && e.target.closest ? e.target.closest('[data-nm-upsell]') : null;
      if (!f) return;
      e.preventDefault();
      var btn = f.querySelector('.nm-upsell-add');
      if (btn) { btn.disabled = true; btn.textContent = '\u2026'; }
      fetch('/cart/add.js', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id: Number(f.querySelector('[name=id]').value), quantity: 1 })
      }).then(function (r) {
        if (!r.ok) throw new Error('add failed');
        window.location.reload();
      }).catch(function () {
        if (btn) { btn.disabled = false; btn.textContent = 'Ajouter'; }
        f.removeAttribute('data-nm-upsell');
        f.submit();
      });
    }, true);
  })();
</script>
